sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.panel {
  border-radius: 12px;
  border: 1px solid #dcdcdc;
  padding: 20px;
  background-color: #fefefe;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.03);
}

.table-rounded {
  border: 1px solid #e0e0e0;
  border-radius: 12px;
  border-collapse: separate;
  border-spacing: 0;
  overflow: hidden;
  width: 100%;
  background-color: #ffffff;
}

.table-rounded th,
.table-rounded td {
  padding: 12px 16px;
  border-bottom: 1px solid #f0f0f0;
}

.table-rounded th {
  background-color: #f3f7fb; /* azzurro molto chiaro */
  font-weight: 600;
  color: #2f4f4f;
  text-align: left;
}

.table-rounded tr:nth-child(even) {
  background-color: #fafafa; /* grigio molto chiaro per righe alternate */
}

/* Rimosso l'effetto hover */
/*
.table-rounded tr:hover {
  background-color: #f1f1f1;
}
*/

.section-title {
  font-size: 20px;
  margin-bottom: 20px;
  display: flex;
  align-items: center;
  color: #007863;
}

.icon-title {
  font-size: 22px;
  margin-right: 10px;
  color: #007863;
}

.label-status {
  font-size: 14px;
  padding: 5px 10px;
  border-radius: 12px;
  display: inline-block;
  min-width: 60px;
  text-align: center;
  filter: none !important;
  color: #fff !important;
}

.label-success {
  background-color: #b7e4c7 !important;
  color: #1b4332 !important;
}

.label-danger {
  background-color: #f8d7da !important;
  color: #721c24 !important;
}

sp_widget.script:
(function() {
    data.showWidget = false;
    data.utenti = [];

    var currentUser = gs.getUser();
    var utenteGR = new GlideRecord('x_1763019_furgonch_utente');
    utenteGR.addQuery('sys_id', currentUser.getID());
    utenteGR.query();

    if (utenteGR.next() && utenteGR.getValue('ruolo_utente').toLowerCase() == 'operatore') {
        data.showWidget = true;

        var clienti = [];
        var operatori = [];

        var utentiGR = new GlideRecord('x_1763019_furgonch_utente');
        utentiGR.query();
        while (utentiGR.next()) {
            var ruolo = utentiGR.getDisplayValue('ruolo_utente') || '';
            var utenteData = {
                username: utentiGR.getValue('user_name'),
                nome: utentiGR.getDisplayValue('first_name'),
                cognome: utentiGR.getDisplayValue('last_name'),
                email: utentiGR.getValue('email'),
                ruolo: ruolo,
                sottoruolo: utentiGR.getDisplayValue('sottoruolo_operatore'),
                credito: (ruolo.toLowerCase() === 'cliente') ? utentiGR.getValue('credito') : null
            };

            if (ruolo.toLowerCase() === 'cliente') {
                clienti.push(utenteData);
            } else if (ruolo.toLowerCase() === 'operatore') {
                operatori.push(utenteData);
            } else {
                // eventuali altri ruoli imprevisti
                data.utenti.push(utenteData);
            }
        }

        // Ordine finale: prima clienti, poi operatori (inverti se vuoi il contrario)
        data.utenti = operatori.concat(clienti);
    }
})();
